    main_set = set(main)
    outsiders = Counter(grid[r][c] for r in range(h) for c in range(w)
                        if grid[r][c] != bg and (r, c) not in main_set)
    marker_color = outsiders.most_common(1)[0][0]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker_color]
    top, bottom = min(r for r, c in main), max(r for r, c in main)
    left, right = min(c for r, c in main), max(c for r, c in main)
    ar, ac = (bottom - top) // 2, (right - left) // 2
    out = [row[:] for row in grid]
    for mr, mc in markers:
