        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                val = grid[r][c]
                if val != bg:
                    y, x = origin_r + (r - top), origin_c + (c - left)
                    if 0 <= y < h and 0 <= x < w:
                        out[y][x] = val
    return out
